//! Bounded JSON/base64 codecs. Errors never contain source values or parser text.
use base64::{engine::general_purpose::STANDARD, Engine};
use serde::de::{self, MapAccess, SeqAccess, Visitor};
use serde::{Deserialize, Deserializer, Serialize};
use serde_json::{Map, Number, Value};
use std::fmt;
use zeroize::{Zeroize, Zeroizing};

use crate::{Error, Result};

pub const MAX_WIRE: usize = 2 * 1024 * 1024;
pub const MAX_BODY: usize = 1024 * 1024;
pub const MAX_RESPONSE_BODY: usize = 8 * MAX_BODY;
pub const MAX_RESPONSE_WIRE: usize = 2 * MAX_RESPONSE_BODY;
pub const MAX_CREDENTIALS: usize = 1024 * 1024;

struct Unique(Value);
fn wipe_value(value: &mut Value) {
    match value {
        Value::String(text) => text.zeroize(),
        Value::Array(values) => {
            for value in values {
                wipe_value(value);
            }
        }
        Value::Object(values) => {
            for (mut key, mut value) in std::mem::take(values) {
                key.zeroize();
                wipe_value(&mut value);
            }
        }
        _ => (),
    }
}
impl Drop for Unique {
    fn drop(&mut self) {
        wipe_value(&mut self.0);
    }
}

impl<'de> Deserialize<'de> for Unique {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> std::result::Result<Self, D::Error> {
        struct JsonVisitor;
        impl<'de> Visitor<'de> for JsonVisitor {
            type Value = Unique;
            fn expecting(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str("bounded protocol JSON")
            }
            fn visit_bool<E: de::Error>(self, v: bool) -> std::result::Result<Unique, E> {
                Ok(Unique(Value::Bool(v)))
            }
            fn visit_unit<E: de::Error>(self) -> std::result::Result<Unique, E> {
                Ok(Unique(Value::Null))
            }
            fn visit_u64<E: de::Error>(self, v: u64) -> std::result::Result<Unique, E> {
                Ok(Unique(Value::Number(Number::from(v))))
            }
            fn visit_i64<E: de::Error>(self, v: i64) -> std::result::Result<Unique, E> {
                Ok(Unique(Value::Number(Number::from(v))))
            }
            fn visit_str<E: de::Error>(self, v: &str) -> std::result::Result<Unique, E> {
                if !v.is_ascii() {
                    return Err(E::custom("invalid string"));
                }
                Ok(Unique(Value::String(v.to_owned())))
            }
            fn visit_seq<A: SeqAccess<'de>>(
                self,
                mut a: A,
            ) -> std::result::Result<Unique, A::Error> {
                let mut guarded = Unique(Value::Array(Vec::new()));
                let values = guarded.0.as_array_mut().expect("array");
                while let Some(mut value) = a.next_element::<Unique>()? {
                    if values.len() >= 4096 {
                        return Err(de::Error::custom("array limit"));
                    }
                    values.push(value.0.take());
                }
                Ok(guarded)
            }
            fn visit_map<A: MapAccess<'de>>(
                self,
                mut a: A,
            ) -> std::result::Result<Unique, A::Error> {
                let mut guarded = Unique(Value::Object(Map::new()));
                let values = guarded.0.as_object_mut().expect("object");
                while let Some(key) = a.next_key::<String>()? {
                    if !key.is_ascii() || values.contains_key(&key) || values.len() >= 4096 {
                        return Err(de::Error::custom("invalid object"));
                    }
                    let mut value: Unique = a.next_value()?;
                    values.insert(key, value.0.take());
                }
                Ok(guarded)
            }
        }
        deserializer.deserialize_any(JsonVisitor)
    }
}

pub fn parse<T: serde::de::DeserializeOwned>(bytes: &[u8], limit: usize) -> Result<T> {
    if bytes.is_empty() || bytes.len() > limit {
        return Err(Error::InvalidMessage);
    }
    let validated: Unique = serde_json::from_slice(bytes).map_err(|_| Error::InvalidMessage)?;
    drop(validated);
    serde_json::from_slice(bytes).map_err(|_| Error::InvalidMessage)
}

pub fn canonical<T: Serialize>(value: &T) -> Result<Vec<u8>> {
    // serde_json's default Map is sorted. Round-trip through the strict reader
    // also rejects floats/non-ASCII generated by a future caller.
    let bytes = Zeroizing::new(serde_json::to_vec(value).map_err(|_| Error::InvalidMessage)?);
    let value: Unique = serde_json::from_slice(&bytes).map_err(|_| Error::InvalidMessage)?;
    serde_json::to_vec(&value.0).map_err(|_| Error::InvalidMessage)
}

pub fn encode(bytes: &[u8]) -> String {
    STANDARD.encode(bytes)
}
pub fn decode(encoded: &str, max: usize) -> Result<Vec<u8>> {
    if encoded.len() > max.div_ceil(3) * 4 {
        return Err(Error::InvalidMessage);
    }
    let mut bytes = Zeroizing::new(
        STANDARD
            .decode(encoded)
            .map_err(|_| Error::InvalidMessage)?,
    );
    if bytes.len() > max || Zeroizing::new(encode(&bytes)).as_str() != encoded {
        return Err(Error::InvalidMessage);
    }
    Ok(std::mem::take(&mut *bytes))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[derive(Debug, Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Typed {
        count: u64,
    }
    #[test]
    fn rejects_ambiguous_or_unbounded_json() {
        for text in [
            r#"{"count":1,"count":2}"#,
            r#"{"count":true}"#,
            r#"{"count":1.0}"#,
            r#"{"count":-1}"#,
            r#"{"count":1,"secret":2}"#,
            r#"{"count":18446744073709551616}"#,
        ] {
            assert!(parse::<Typed>(text.as_bytes(), 1024).is_err());
        }
        assert_eq!(parse::<Typed>(br#"{"count":2}"#, 1024).unwrap().count, 2);
        assert!(parse::<Typed>(br#"{"count":2}"#, 2).is_err());
        assert!(parse::<Value>(br#"{"nested":{"x":1,"x":2}}"#, 1024).is_err());
        assert!(parse::<Value>(br#"{"x":"\u00e9"}"#, 1024).is_err());
    }
    #[test]
    fn canonical_vector() {
        let value: Value = parse(br#"{"z":null,"a":[true,{"b":2,"a":1}]}"#, 1024).unwrap();
        assert_eq!(
            canonical(&value).unwrap(),
            br#"{"a":[true,{"a":1,"b":2}],"z":null}"#
        );
    }
    #[test]
    fn strict_base64() {
        assert_eq!(decode("Zg==", 1).unwrap(), b"f");
        for value in ["Zg", "Zh==", "Zg==\n", "-_==", "Zm8="] {
            assert!(decode(value, 1).is_err());
        }
    }
}
